# frozen_string_literal: true

# Generated by Descant: acceptance tests.

require "rails_helper"

RSpec.describe "Timekeeping service commands: a failed outbox insert" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # Issue: "Every reservation change that flips `locked`, every mark-billed and
  # every detach writes an audit row and an outbox snapshot row in the same
  # transaction as the change."
  it "rolls back mark-billed and detach-entries when the outbox insert fails, then runs the retry as a first attempt" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    billable = arrange.reserved_entry(company:, invoice_id: 501, state: "committed")
    agent_entry = arrange.entry(company:, user: arrange.user(company:, role: "employee"),
                                project: arrange.project(company:), agent_id: 77)
    mark_key = SecureRandom.uuid
    detach_key = SecureRandom.uuid
    command = lambda do |path, key|
      post path, params: { "operation_id" => key, "generation" => arrange.current_generation }.to_json,
                 headers: { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
      response
    rescue StandardError
      nil
    end
    mark_path = "/v1/companies/#{company}/invoices/501/mark-billed"
    detach_path = "/v1/companies/#{company}/agents/77/detach-entries"
    counts = [AuditEvent.count, OutboxSnapshot.count, IdempotencyReceipt.count, Entry.sum(:version)]

    allow(OutboxSnapshot).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "outbox down")
    command.call(mark_path, mark_key)
    command.call(detach_path, detach_key)

    expect(Entry.find(billable).bill_status).to eq("unbilled")
    expect(Entry.find(agent_entry).agent_id).to eq(77)
    expect([AuditEvent.count, OutboxSnapshot.count, IdempotencyReceipt.count, Entry.sum(:version)]).to eq(counts)

    allow(OutboxSnapshot).to receive(:insert_all!).and_call_original
    expect(JSON.parse(command.call(mark_path, mark_key).body)).to eq("billed" => 1)
    expect(JSON.parse(command.call(detach_path, detach_key).body)).to eq("detached" => 1)
    expect(AuditEvent.where(entry_id: [billable, agent_entry]).count).to eq(2)
    expect(OutboxSnapshot.where(id: [billable, agent_entry]).count).to eq(2)
  end
end

RSpec.describe "Timekeeping reservation commit: a failed outbox insert" do
  include_context "timekeeping entry writes"
  include_context "timekeeping entry writes without transactional fixtures"

  # Issue: "Every reservation change that flips `locked`, every mark-billed and
  # every detach writes an audit row and an outbox snapshot row in the same
  # transaction as the change." A commit whose outbox insert fails must not
  # record a terminal state, or its retry would answer as a replay of work
  # that never happened.
  it "leaves the operation prepared and reservations untouched when the commit's outbox insert fails" do
    arrange = timekeeping_arrange
    company = arrange.company
    service = arrange.service_identity(company:, name: "invoice-boundary",
                                       operations: %w[prepare commit abort mark_billed detach_entries])
    user = arrange.user(company:, role: "employee")
    project = arrange.project(company:)
    kept = arrange.entry(company:, user:, project:)
    dropped = arrange.entry(company:, user:, project:)
    command = lambda do |route, operation_id, extra = {}|
      post "/v1/companies/#{company}/reservations/#{route}",
           params: { "invoice_id" => 501, "operation_id" => operation_id,
                     "generation" => arrange.current_generation }.merge(extra).to_json,
           headers: { "Authorization" => "Bearer #{service}", "Content-Type" => "application/json" }
      response
    rescue StandardError
      nil
    end
    first = SecureRandom.uuid
    command.call("prepare", first, "disposition" => "active", "entries" => [kept, dropped])
    command.call("commit", first)
    second = SecureRandom.uuid
    expect(command.call("prepare", second, "disposition" => "active", "entries" => [kept]).status).to eq(200)
    before = Reservation.order(:entry_id).pluck(:entry_id, :invoice_id, :state)
    counts = [AuditEvent.count, OutboxSnapshot.count, IdempotencyReceipt.count, Entry.sum(:version)]

    allow(OutboxSnapshot).to receive(:insert_all!).and_raise(ActiveRecord::StatementInvalid, "outbox down")
    command.call("commit", second)

    expect(Reservation.order(:entry_id).pluck(:entry_id, :invoice_id, :state)).to eq(before)
    expect([AuditEvent.count, OutboxSnapshot.count, IdempotencyReceipt.count, Entry.sum(:version)]).to eq(counts)

    allow(OutboxSnapshot).to receive(:insert_all!).and_call_original
    expect(JSON.parse(command.call("commit", second).body)).to eq("reserved" => 0, "released" => 1)
    expect(Reservation.where(entry_id: dropped).count).to eq(0)
  end
end
